import os
from typing import Any, Dict, Optional

import requests


class ContentSafetyError(Exception):
    pass


def _get_float_env(name: str, default: float) -> float:
    raw = os.getenv(name)
    if raw is None or raw.strip() == "":
        return default
    try:
        value = float(raw)
    except ValueError as exc:
        raise ContentSafetyError(f"Invalid float for {name}: {raw}") from exc
    if value < 0:
        raise ContentSafetyError(f"{name} must be non-negative")
    return value


def _normalize_category_scores(result: Dict[str, Any]) -> Dict[str, float]:
    scores: Dict[str, float] = {}

    if isinstance(result.get("attributeScores"), dict):
        for category, payload in result["attributeScores"].items():
            score = None
            if isinstance(payload, dict):
                summary = payload.get("summaryScore")
                if isinstance(summary, dict) and "value" in summary:
                    score = summary["value"]
                elif "value" in payload:
                    score = payload["value"]
            if score is not None:
                try:
                    scores[category] = float(score)
                except (TypeError, ValueError):
                    continue
        return scores

    if isinstance(result.get("categories"), dict):
        for category, score in result["categories"].items():
            try:
                scores[str(category)] = float(score)
            except (TypeError, ValueError):
                continue
        return scores

    if isinstance(result.get("categoryScores"), dict):
        for category, score in result["categoryScores"].items():
            try:
                scores[str(category)] = float(score)
            except (TypeError, ValueError):
                continue
        return scores

    return scores


def should_allow_text(text: str, thresholds: Optional[Dict[str, float]] = None) -> bool:
    """
    Applies category thresholds to decide whether to allow text using Perspective API.

    Default thresholds can be overridden via:
      - PERSPECTIVE_API_KEY (required)
      - PERSPECTIVE_TOXICITY_THRESHOLD
      - PERSPECTIVE_SEVERE_TOXICITY_THRESHOLD
      - PERSPECTIVE_INSULT_THRESHOLD
      - PERSPECTIVE_PROFANITY_THRESHOLD
      - PERSPECTIVE_THREAT_THRESHOLD
      - PERSPECTIVE_SEXUALLY_EXPLICIT_THRESHOLD
      - PERSPECTIVE_IDENTITY_ATTACK_THRESHOLD

    Returns True when the text is allowed, False otherwise.
    """
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ContentSafetyError("Missing required environment variable: PERSPECTIVE_API_KEY")

    default_thresholds = {
        "TOXICITY": _get_float_env("PERSPECTIVE_TOXICITY_THRESHOLD", 0.70),
        "SEVERE_TOXICITY": _get_float_env("PERSPECTIVE_SEVERE_TOXICITY_THRESHOLD", 0.60),
        "INSULT": _get_float_env("PERSPECTIVE_INSULT_THRESHOLD", 0.70),
        "PROFANITY": _get_float_env("PERSPECTIVE_PROFANITY_THRESHOLD", 0.80),
        "THREAT": _get_float_env("PERSPECTIVE_THREAT_THRESHOLD", 0.50),
        "SEXUALLY_EXPLICIT": _get_float_env("PERSPECTIVE_SEXUALLY_EXPLICIT_THRESHOLD", 0.70),
        "IDENTITY_ATTACK": _get_float_env("PERSPECTIVE_IDENTITY_ATTACK_THRESHOLD", 0.60),
    }
    if thresholds:
        default_thresholds.update({k.upper(): float(v) for k, v in thresholds.items()})

    url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    params = {"key": api_key}
    payload = {
        "comment": {"text": text},
        "languages": ["en"],
        "requestedAttributes": {category: {} for category in default_thresholds.keys()},
        "doNotStore": True,
    }

    response = requests.post(url, params=params, json=payload, timeout=30)
    if response.status_code >= 400:
        raise ContentSafetyError(f"Perspective API request failed ({response.status_code}): {response.text}")

    data = response.json()
    scores = _normalize_category_scores(data)

    for category, threshold in default_thresholds.items():
        score = scores.get(category)
        if score is not None and score >= threshold:
            return False

    return True
